fn test_parse_def_purity_with_other_modifiers() {
	// `pure` stacks with `scope=` and `[returns]` in any order.
	src := '[?def add scope=public pure [returns int] ($a::int $b::int) [+ a b]]'
	n := cx.parse_def(src) or {
		assert false, 'parse failed: ${err}'
