// ── `:bind` equality + hashing (identity-relevant) ────────────

fn test_parse_path_bind_eq_distinguishes_bindings() {
	// Two PathNodes differing ONLY in the `:bind NAME` should compare
	// unequal under .eq() — the binding is identity-relevant because it
	// changes the path's downstream visible names.
	a := cx.PathNode{
		form:  cx.PathForm.descendant
		steps: [cx.PathStep{ axis: cx.PathAxis.child, node_test: 'user',
		                     binding: 'u' }]
	}
	b := cx.PathNode{
		form:  cx.PathForm.descendant
		steps: [cx.PathStep{ axis: cx.PathAxis.child, node_test: 'user',
		                     binding: 'v' }]
	}
	assert !a.eq(b)
	// And vs. a no-binding step:
	c := cx.PathNode{
		form:  cx.PathForm.descendant
		steps: [cx.PathStep{ axis: cx.PathAxis.child, node_test: 'user' }]
	}
	assert !a.eq(c)
}

fn test_parse_path_bind_hash_distinguishes_bindings() {
	// Canonical-bytes hashing includes step.binding when present, so
	// two otherwise-equal paths with different bindings hash distinct.
	a := cx.PathNode{
		form:  cx.PathForm.descendant
		steps: [cx.PathStep{ axis: cx.PathAxis.child, node_test: 'user',
		                     binding: 'u' }]
	}
	b := cx.PathNode{
		form:  cx.PathForm.descendant
		steps: [cx.PathStep{ axis: cx.PathAxis.child, node_test: 'user',
		                     binding: 'v' }]
	}
	assert cx.path_node_hash(a) != cx.path_node_hash(b)
	// A binding-less step also hashes distinct from a binding-bearing one.
	c := cx.PathNode{
		form:  cx.PathForm.descendant
		steps: [cx.PathStep{ axis: cx.PathAxis.child, node_test: 'user' }]
	}
	assert cx.path_node_hash(a) != cx.path_node_hash(c)
}

fn test_parse_path_bind_parsed_eq_hand_constructed() {
	// Parser-produced PathNode with `:bind` compares equal to a hand-
	// constructed shape carrying the same binding.
	parsed := cx.parse_path('//user :bind u') or {
		assert false, 'parse failed: ${err}'
		return
	}
	hand := cx.PathNode{
		form:  cx.PathForm.descendant
		steps: [cx.PathStep{ axis: cx.PathAxis.child, node_test: 'user',
		                     binding: 'u' }]
	}
	assert parsed.eq(hand)
	assert hand.eq(parsed)
}

// ── source: vcx/tests/path_renderer_test.v ──
// Tests for the Phase 2.9 PathNode canonical renderer
// (`vcx/cx/path_renderer.v`) per `spec/canonical.md §2.12`.
//
// Coverage map:
//   §2.12.2 form discriminator (absolute / descendant / relative /
//           binding)            — test_render_form_*
//   §2.12.3 axis emit (child omitted, attribute → @, others
//           `axis::`)           — test_render_axis_*
//   §2.12.4 node-test verbatim  — test_render_node_test_*
//   §2.12.5 predicate `[BODY]`  — test_render_predicate_*
//   §2.12.6 zero whitespace     — test_render_no_whitespace
//   §2.12.7 identity round-trip — test_identity_round_trip_*
//   §2.12.8 worked examples     — test_worked_example_*
//
// The worked-example suite (test_worked_example_*) covers all eight
// rows of the §2.12.8 table.
// ── §2.12.8 worked examples ───────────────────────────────────────────────────

fn test_worked_example_1_descendant_bare() {
	// `form=descendant`, step `(child, user, [])` → `//user`
	node := cx.PathNode{
		form:  cx.PathForm.descendant
		steps: [cx.PathStep{ axis: cx.PathAxis.child, node_test: 'user' }]
	}
	assert cx.render_path(node) == '//user'
}

