fn test_bom_at_start_consumed() {
	t := cx.tokenize('\xEF\xBB\xBFfoo') or { panic(err) }
	assert kinds(t) == [cx.ProgramTokenKind.ident, .eof]
	assert t[0].text == 'foo'
}

// ── Position tracking ───────────────────────────────────────────────────────

fn test_position_tracks_line_and_col() {
	t := cx.tokenize('a\n  b') or { panic(err) }
	// 'a' at line 1 col 1
	assert t[0].pos.line == 1
	assert t[0].pos.col == 1
	// 'b' at line 2 col 3
	assert t[1].pos.line == 2
	assert t[1].pos.col == 3
}

// ── Composite fixtures matching conformance/code.txt shapes ──────────────────

fn test_find_directive_with_pattern() {
	src := '[?for [user [email \$e]] :yield \$e]'
	t := cx.tokenize(src) or { panic(err) }
	// Expected sequence:
	//   [?for   → directive_name "for"
	//   [       → lbrack
	//   user    → ident
	//   [       → lbrack
	//   email   → ident
	//   \$      → dollar
	//   e       → ident
	//   ]       → rbrack
	//   ]       → rbrack
	//   :       → colon
	//   yield   → ident
	//   \$      → dollar
	//   e       → ident
	//   ]       → rbrack
	//   eof
	assert kinds(t) == [
		cx.ProgramTokenKind.directive_name, .lbrack, .ident, .lbrack, .ident,
		.dollar, .ident, .rbrack, .rbrack, .colon, .ident, .dollar,
		.ident, .rbrack, .eof,
	]
	assert t[0].text == 'for'
}

fn test_retry_with_duration_and_pipe() {
	src := '[?retry :max 3 :delay 100ms :body fetch() | dump]'
	t := cx.tokenize(src) or { panic(err) }
	assert t[0].kind == .directive_name && t[0].text == 'retry'
	// Find the duration_lit token.
	mut dur_idx := -1
	for i, tok in t {
		if tok.kind == .duration_lit {
			dur_idx = i
			break
		}
	}
	assert dur_idx > 0
	assert t[dur_idx].text == '100ms'
	// And the pipe token.
	mut pipe_count := 0
	for tok in t {
		if tok.kind == .pipe {
			pipe_count++
		}
	}
	assert pipe_count == 1
}

fn test_empty_source_yields_eof_only() {
	t := cx.tokenize('') or { panic(err) }
	assert kinds(t) == [cx.ProgramTokenKind.eof]
}

fn test_unexpected_char_errors() {
	cx.tokenize('foo \x07 bar') or {
		assert err is cx.LexError
		return
	}
	assert false, 'unexpected byte should be a LexError'
}

// ── source: vcx/tests/call_result_steps_test.v ──
// call_result_steps_test.v — the CRS-1 call-result postfix-step gate (#862).
//
// RULED CRS-1 (2026-08-20, owner 862b; ledger/rulings_2026_08_20_call_result_steps.md):
// a head-dispatch call result carries the grammar [135a] compact-step
// subset — `[$first $h]@v`, `[$nth $xs $i]/*`, `[$paint $doc]//l` —
// byte-adjacency-gated exactly like the binding step loop, with the SAME
// BP-1 explicit-axis refusal. Stepping a call result is semantically
// identical to binding the result and stepping the binding:
//   [$string [$f …]/name] ≡ [?let [= $t [$f …]] [$string $t/name]]
// This gate pins the parse surface (both call forms, adjacency,
// refusals), the eval equivalence, and the canonical-emit round-trip.
// ── helpers ─────────────────────────────────────────────────────────

fn crs_parse(src string) cx.Program {
	return cx.parse_program(src) or { panic('parse failed for `${src}`: ${err.msg()}') }
}

fn crs_eval_canon(src string) string {
	n := code.program_parse_to_typed_node(src) or {
		assert false, 'eval failed for `${src}`'
		return ''
	}
	return code.render_canonical(n)
}

// ── parse: the [135a] steps attach to the call RESULT ───────────────

fn test_parse_attr_step_on_call_result() {
	body := crs_parse('[\$first \$h]@v').body
	if body is cx.ProgramCall {
		assert body.name == 'first'
		assert body.args.len == 1
		assert body.path.len == 1, 'expected one postfix step, got ${body.path.len}'
		assert body.path[0].kind == .attr
		assert body.path[0].name == 'v'
	} else {
		assert false, 'expected ProgramCall'
	}
}

fn test_parse_wildcard_and_descendant_on_call_result() {
	w := crs_parse('[\$nth \$xs \$i]/*').body
	if w is cx.ProgramCall {
		assert w.path.len == 1
		assert w.path[0].kind == .wildcard_children
	} else {
		assert false, 'expected ProgramCall for /*'
	}
	d := crs_parse('[\$paint \$doc]//l').body
	if d is cx.ProgramCall {
		assert d.path.len == 1
		assert d.path[0].kind == .descendant
		assert d.path[0].name == 'l'
	} else {
		assert false, 'expected ProgramCall for //l'
	}
}

fn test_parse_predicate_on_call_result_step() {
	body := crs_parse('[\$first \$h]/item[1]/name').body
	if body is cx.ProgramCall {
		assert body.path.len == 2
		assert body.path[0].kind == .child
		assert body.path[0].name == 'item'
		assert body.path[0].predicates.len == 1, 'adjacent [1] must be a step predicate'
		assert body.path[1].name == 'name'
	} else {
		assert false, 'expected ProgramCall'
	}
}

fn test_parse_chained_steps_after_postfix_marker() {
	// The step run follows the `?`/`!` postfix (grammar [125] order).
	body := crs_parse('[\$f \$x]?/name').body
	if body is cx.ProgramCall {
		assert body.fallible
		assert body.path.len == 1
		assert body.path[0].name == 'name'
	} else {
		assert false, 'expected ProgramCall'
	}
}

fn test_parse_whitespace_separated_step_token_stays_operand() {
	// `[$count //*]` is head-plus-argument (the pre-CRS-1 adjacency rule,
	// unchanged): NO postfix path on the call.
	body := crs_parse('[\$count //*]').body
	if body is cx.ProgramCall {
		assert body.name == 'count'
		assert body.args.len == 1
		assert body.path.len == 0, 'a spaced //* must stay a call argument'
	} else {
		assert false, 'expected ProgramCall'
	}
}

fn test_parse_qualified_call_carries_postfix_steps() {
	body := crs_parse('[m/f \$x]@v').body
	if body is cx.ProgramCall {
		assert body.path.len == 1
		assert body.path[0].kind == .attr
		assert body.path[0].name == 'v'
	} else {
		assert false, 'expected ProgramCall for the qualified form'
	}
}

// ── parse: refusals — one surface, the BP-1 wording ─────────────────

fn test_parse_axis_on_call_result_refuses_with_bp1_message() {
	cx.parse_program('[\$f \$x]/ancestor::y') or {
		msg := err.msg()
		assert msg.contains('not binding-path surface'), 'expected the BP-1 diagnostic, got: ${msg}'
		assert msg.contains('135a'), 'the diagnostic names grammar [135a]: ${msg}'
		return
	}
	assert false, 'explicit axis on a call result must refuse (BP-1/CRS-1)'
}

fn test_parse_call_head_steps_still_refused() {
	cx.parse_program('[\$fn/x 1]') or {
		assert err.msg().contains('bind the value first'), 'head refusal wording moved: ${err.msg()}'
		return
	}
	assert false, 'steps on a call HEAD must stay refused (a head is a name, not a value)'
}

// ── canonical emit: the steps round-trip ────────────────────────────

fn test_canonical_emit_round_trips_call_result_steps() {
	src := '[\$first \$h]@v'
	body := crs_parse(src).body
	emitted := code.program_node_to_source(body)
	assert emitted == src, 'canonical emit must re-emit the glued postfix: ${emitted}'
	reparsed := crs_parse(emitted).body
	if reparsed is cx.ProgramCall {
		assert reparsed.path.len == 1
		assert reparsed.path[0].kind == .attr
	} else {
		assert false, 'reparse of emitted source must keep the postfix'
	}
}

// ── eval: the issue repro + the [?let]-equivalence pin ──────────────

fn test_eval_attr_on_call_result_issue_repro() {
	// #862 repro: previously `unexpected token '@' in expression position`.
	out := crs_eval_canon('[?let [= \$h ([row v=1], [row v=2])] [report [\$first \$h]@v]]')
	assert out.contains('1'), 'expected the first row attr value, got: ${out}'
	assert !out.contains('err'), 'repro must evaluate cleanly: ${out}'
}

fn test_eval_let_equivalence_pin() {
	// [$string [$f …]/name] ≡ [?let [= $t [$f …]] [$string $t/name]]
	direct := crs_eval_canon('[?let [= \$h ([row v=1 [name "a"]], [row v=2 [name "b"]])] [\$string [\$first \$h]/name]]')
	via_let := crs_eval_canon('[?let [= \$h ([row v=1 [name "a"]], [row v=2 [name "b"]])] [?let [= \$t [\$first \$h]] [\$string \$t/name]]]')
	assert direct == via_let, 'call-result step must equal bind-then-step: `${direct}` vs `${via_let}`'
}

fn test_eval_equivalence_attr_and_wildcard() {
	d1 := crs_eval_canon('[?let [= \$h ([row v=1], [row v=2])] [\$last \$h]@v]')
	v1 := crs_eval_canon('[?let [= \$h ([row v=1], [row v=2])] [?let [= \$t [\$last \$h]] \$t@v]]')
	assert d1 == v1, '@attr equivalence: `${d1}` vs `${v1}`'
	d2 := crs_eval_canon('[?let [= \$h ([row [a 1] [b 2]], [row [c 3]])] [\$first \$h]/*]')
	v2 := crs_eval_canon('[?let [= \$h ([row [a 1] [b 2]], [row [c 3]])] [?let [= \$t [\$first \$h]] \$t/*]]')
	assert d2 == v2, '/* equivalence: `${d2}` vs `${v2}`'
}

fn test_eval_predicate_on_call_result_step() {
	d := crs_eval_canon('[?let [= \$h ([u [item 1] [item 2] [item 3]], [u [item 9]])] [\$first \$h]/item[2]]')
	v := crs_eval_canon('[?let [= \$h ([u [item 1] [item 2] [item 3]], [u [item 9]])] [?let [= \$t [\$first \$h]] \$t/item[2]]]')
	assert d == v, 'predicate-step equivalence: `${d}` vs `${v}`'
	assert d.contains('2'), 'positional predicate must pick the second item: ${d}'
}

fn test_eval_descendant_chain_on_call_result() {
	d := crs_eval_canon('[?let [= \$h ([u [team [member id=1]]], [u [team [member id=2]]])] [\$last \$h]//member@id]')
	v := crs_eval_canon('[?let [= \$h ([u [team [member id=1]]], [u [team [member id=2]]])] [?let [= \$t [\$last \$h]] \$t//member@id]]')
	assert d == v, 'descendant+attr equivalence: `${d}` vs `${v}`'
	assert d.contains('2'), 'the last row descendant id: ${d}'
}

fn test_eval_step_distribution_over_sequence_result() {
	// ARR-1 / O4 agreement: a step over a sequence-returning call
	// distributes over its members, exactly as over a bound sequence.
	d := crs_eval_canon('[?let [= \$h ([row v=1], [row v=2], [row v=3])] [\$tail \$h]@v]')
	v := crs_eval_canon('[?let [= \$h ([row v=1], [row v=2], [row v=3])] [?let [= \$t [\$tail \$h]] \$t@v]]')
	assert d == v, 'O4 distribution equivalence: `${d}` vs `${v}`'
	assert d.contains('2') && d.contains('3'), 'tail members must both contribute: ${d}'
}

fn test_eval_map_key_step_on_call_result() {
	d := crs_eval_canon('[?let [= \$m {name: "zed", meta: {rank: 4}}] [\$identity \$m].meta.rank]')
	assert d.contains('4'), 'map-key chain on a call result: ${d}'
}

// ── source: vcx/tests/postfix_step_uniformity_test.v ──
// postfix_step_uniformity_test.v — the PS-1 postfix-step uniformity gate (#886).
//
// RULED PS-1 (2026-08-20, owner "1a"; ledger/rulings_2026_08_20_postfix_uniformity.md):
// EVERY program-position bracketed form's closing bracket accepts the
// grammar [135a] compact-step postfix — directive results ([?let]/[?if]/
// [?match]/[?for]/…), operator forms, element literals, and collection
// literals — byte-adjacency-gated exactly like the binding step loop
// (BP-1 axis refusals inherited from the ONE shared step parser; CRS-1
// gave calls the same surface). Semantics: ZERO new — stepping any
// form's result is identical to binding the result and stepping the
// binding:
//   [?let …]/name ≡ [?let [= $t [?let …]] $t/name]      (any head)
// This gate pins, PER HEAD CLASS: the parse surface (steps land on the
// node's path), a positive step, an @attr step, the let-equivalence,
// the BP-1 axis refusal, the adjacency rule (spaced stays separate),
// and the canonical-emit round-trip.
// ── helpers ─────────────────────────────────────────────────────────

fn ps_parse(src string) cx.Program {
	return cx.parse_program(src) or { panic('parse failed for `${src}`: ${err.msg()}') }
}

fn ps_eval_canon(src string) string {
	n := code.program_parse_to_typed_node(src) or {
		assert false, 'eval failed for `${src}`'
		return ''
	}
	return code.render_canonical(n)
}

// ps_eval_any captures BOTH outcome channels — the canonical rendering of
// a value result, or the thrown error's message — so refusal equivalences
// (`@attr` on a non-element result vs on a binding of it) compare exactly.
fn ps_eval_any(src string) string {
	return code.eval_code('', src, 'text') or {
		if err is code.EvalError {
			return 'error: ${err.code}: ${err.message}'
		}
		return 'error: ${err.msg()}'
	}
}

fn ps_assert_axis_refusal(src string) {
	cx.parse_program(src) or {
		msg := err.msg()
		assert msg.contains('not binding-path surface'), 'expected the BP-1 diagnostic for `${src}`, got: ${msg}'
		assert msg.contains('135a'), 'the diagnostic names grammar [135a]: ${msg}'
		return
	}
	assert false, 'explicit axis must refuse (BP-1/PS-1): `${src}`'
}

// ── directive results: [?let] ────────────────────────────────────────

fn test_parse_step_on_let_result() {
	body := ps_parse('[?let [= \$u [user [b 1]]] \$u]/b').body
	if body is cx.ProgramDirective {
		assert body.name == 'let'
		assert body.path.len == 1, 'expected one postfix step, got ${body.path.len}'
		assert body.path[0].kind == .child
		assert body.path[0].name == 'b'
	} else {
		assert false, 'expected ProgramDirective for the stepped [?let]'
	}
}

fn test_eval_let_result_step_and_equivalence() {
	direct := ps_eval_canon('[?let [= \$u [user [name "ann"]]] \$u]/name')
	assert direct.contains('ann'), 'child step on a [?let] result: ${direct}'
	via_let := ps_eval_canon('[?let [= \$t [?let [= \$u [user [name "ann"]]] \$u]] \$t/name]')
	assert direct == via_let, '[?let]-equivalence (directive head): `${direct}` vs `${via_let}`'
}

fn test_eval_let_result_attr_step() {
	d := ps_eval_canon('[?let [= \$r [row v=9]] \$r]@v')
	v := ps_eval_canon('[?let [= \$t [?let [= \$r [row v=9]] \$r]] \$t@v]')
	assert d == v, '@attr equivalence (directive head): `${d}` vs `${v}`'
	assert d.contains('9'), 'attr step on a [?let] result: ${d}'
}

fn test_parse_axis_on_let_result_refuses() {
	ps_assert_axis_refusal('[?let [= \$x 1] \$x]/ancestor::y')
}

// ── directive results: [?if] ─────────────────────────────────────────

fn test_eval_if_result_steps() {
	d := ps_eval_canon('[?if true [then [user [b 7]]]]/b')
	v := ps_eval_canon('[?let [= \$t [?if true [then [user [b 7]]]]] \$t/b]')
	assert d == v, '[?if] equivalence: `${d}` vs `${v}`'
	assert d.contains('7'), 'child step on an [?if] result: ${d}'
	a := ps_eval_canon('[?if true [then [row v=3]]]@v')
	assert a.contains('3'), '@attr on an [?if] result: ${a}'
}

fn test_parse_axis_on_if_result_refuses() {
	ps_assert_axis_refusal('[?if true [then 1]]/following-sibling::y')
}

// ── directive results: [?match] ──────────────────────────────────────

fn test_eval_match_result_steps() {
	d := ps_eval_canon('[?match 2 [case 2 [user [b 5]]] [else [user [b 0]]]]/b')
	v := ps_eval_canon('[?let [= \$t [?match 2 [case 2 [user [b 5]]] [else [user [b 0]]]]] \$t/b]')
	assert d == v, '[?match] equivalence: `${d}` vs `${v}`'
	assert d.contains('5'), 'child step on a [?match] result: ${d}'
}

fn test_parse_axis_on_match_result_refuses() {
	ps_assert_axis_refusal('[?match 1 [else 2]]/self::y')
}

// ── directive results: [?for] (comprehension) ────────────────────────

fn test_parse_step_on_for_comp_result() {
	body := ps_parse('[?for [in \$u ([row v=1], [row v=2])] [yield \$u]]@v').body
	if body is cx.ProgramForComp {
		assert body.path.len == 1
		assert body.path[0].kind == .attr
		assert body.path[0].name == 'v'
	} else {
		assert false, 'expected ProgramForComp for the stepped [?for]'
	}
}

fn test_eval_for_comp_result_steps() {
	d := ps_eval_canon('[?for [in \$u ([row v=1], [row v=2])] [yield \$u]]@v')
	v := ps_eval_canon('[?let [= \$t [?for [in \$u ([row v=1], [row v=2])] [yield \$u]]] \$t@v]')
	assert d == v, '[?for] @attr equivalence (O4 distribution): `${d}` vs `${v}`'
	assert d.contains('1') && d.contains('2'), 'both members contribute: ${d}'
	c := ps_eval_canon('[?for [in \$u ([user [n 4]], [user [n 6]])] [yield \$u]]/n')
	cv := ps_eval_canon('[?let [= \$t [?for [in \$u ([user [n 4]], [user [n 6]])] [yield \$u]]] \$t/n]')
	assert c == cv, '[?for] child-step equivalence: `${c}` vs `${cv}`'
}

fn test_parse_axis_on_for_result_refuses() {
	ps_assert_axis_refusal('[?for [in \$u (1, 2)] [yield \$u]]/preceding::y')
}

// ── operator forms ───────────────────────────────────────────────────

fn test_parse_step_on_operator_form() {
	body := ps_parse('[+ 1 2]/x').body
	if body is cx.ProgramLiteral {
		assert body.kind == .cx_element
		assert body.name == '+'
		assert body.path.len == 1
		assert body.path[0].kind == .child
		assert body.path[0].name == 'x'
	} else {
		assert false, 'expected the operator-form literal for [+ 1 2]/x'
	}
}

fn test_eval_operator_form_steps_kind_driven() {
	// A child step on a scalar result yields empty — the same footgun
	// shape bindings already have (letter §2.1); NO error.
	d := ps_eval_canon('[report [+ 1 2]/x]')
	v := ps_eval_canon('[report [?let [= \$t [+ 1 2]] \$t/x]]')
	assert d == v, 'operator-form child-step equivalence: `${d}` vs `${v}`'
	// @attr on a non-element result refuses TYPED (CXER0001) — exactly
	// as on a binding of that scalar (both channels compared).
	a := ps_eval_any('[+ 1 2]@a')
	av := ps_eval_any('[?let [= \$t [+ 1 2]] \$t@a]')
	assert a == av, 'operator-form @attr equivalence (typed refusal): `${a}` vs `${av}`'
	assert a.contains('CXER0001'), '@attr on a scalar result refuses typed: ${a}'
}

fn test_parse_axis_on_operator_form_refuses() {
	ps_assert_axis_refusal('[+ 1 2]/ancestor::y')
}

// ── element literals ─────────────────────────────────────────────────

fn test_parse_step_on_element_literal() {
	body := ps_parse('[user [b 1] [c 2]]/c').body
	if body is cx.ProgramLiteral {
		assert body.kind == .cx_element
		assert body.name == 'user'
		assert body.path.len == 1
		assert body.path[0].name == 'c'
	} else {
		assert false, 'expected the element literal for [user …]/c'
	}
}

fn test_eval_element_literal_steps() {
	d := ps_eval_canon('[user [b 1] [c 2]]/c')
	v := ps_eval_canon('[?let [= \$t [user [b 1] [c 2]]] \$t/c]')
	assert d == v, 'element-literal child-step equivalence: `${d}` vs `${v}`'
	assert d.contains('2'), 'redundant-but-legal element step (letter §3a): ${d}'
	a := ps_eval_canon('[row v=4]@v')
	av := ps_eval_canon('[?let [= \$t [row v=4]] \$t@v]')
	assert a == av, 'element-literal @attr equivalence: `${a}` vs `${av}`'
	assert a.contains('4'), '@attr on an element literal: ${a}'
}

fn test_parse_axis_on_element_literal_refuses() {
	ps_assert_axis_refusal('[user [b 1]]/ancestor-or-self::y')
}

// ── collection literals: array / sequence / map ──────────────────────

fn test_parse_step_on_array_literal() {
	body := ps_parse('[1, 2, 3]/x').body
	if body is cx.ProgramLiteral {
		assert body.kind == .array_lit
		assert body.path.len == 1
	} else {
		assert false, 'expected the array literal for [1, 2, 3]/x'
	}
}

fn test_eval_collection_literal_steps() {
	// Array: kind-driven equivalence (child step over scalars → empty).
	d := ps_eval_canon('[report [1, 2]/x]')
	v := ps_eval_canon('[report [?let [= \$t [1, 2]] \$t/x]]')
	assert d == v, 'array-literal equivalence: `${d}` vs `${v}`'
	// Sequence of elements: @attr distributes exactly as on a binding.
	s := ps_eval_canon('([row v=1], [row v=2])@v')
	sv := ps_eval_canon('[?let [= \$t ([row v=1], [row v=2])] \$t@v]')
	assert s == sv, 'sequence-literal @attr equivalence: `${s}` vs `${sv}`'
	assert s.contains('1') && s.contains('2'), 'sequence members contribute: ${s}'
	// Map: `.key` member step.
	m := ps_eval_canon('{a: 5, b: {c: 6}}.b.c')
	mv := ps_eval_canon('[?let [= \$t {a: 5, b: {c: 6}}] \$t.b.c]')
	assert m == mv, 'map-literal member-step equivalence: `${m}` vs `${mv}`'
	assert m.contains('6'), 'nested member step on a map literal: ${m}'
}

fn test_parse_axis_on_collection_literal_refuses() {
	ps_assert_axis_refusal('[1, 2]/ancestor::y')
	ps_assert_axis_refusal('(1, 2)/ancestor::y')
}

// ── adjacency: a spaced step token keeps its current reading ─────────

fn test_whitespace_separated_step_token_stays_separate() {
	// A SPACED `/name` after a directive's `]` is a separate statement
	// (rooted PathExpr), never a result step — the program parses to a
	// block of two statements, the directive path-less.
	prog := ps_parse('[?let [= \$x 1] \$x] /y')
	body := prog.body
	if body is cx.ProgramLiteral {
		assert body.kind == .block, 'expected a two-statement block for the spaced form'
		assert body.items.len == 2
		first := body.items[0]
		if first is cx.ProgramDirective {
			assert first.path.len == 0, 'a spaced /y must not attach to the directive'
		} else {
			assert false, 'first statement must stay the directive'
		}
	} else {
		assert false, 'expected a block for the spaced form, got a single node'
	}
	// Inside an element body: `[cfg /a/b]` keeps its spaced path-operand
	// reading (the [122a] note's pin).
	el := ps_parse('[cfg /a/b]').body
	if el is cx.ProgramLiteral {
		assert el.kind == .cx_element
		assert el.path.len == 0
		assert el.items.len == 1, 'the spaced /a/b stays ONE body operand'
	} else {
		assert false, 'expected the element literal for [cfg /a/b]'
	}
}

// ── canonical emit: the steps round-trip per head class ──────────────

fn test_canonical_emit_round_trips_result_steps() {
	sources := [
		'[?let [= \$u [user [b 1]]] \$u]/b',
		'[?if true [then [row v=1]]]@v',
		'[+ 1 2]/x',
		'[user [b 1] [c 2]]/c',
		'[1, 2]/x',
		'{a: 5}.a',
	]
	for src in sources {
		body := ps_parse(src).body
		emitted := code.program_node_to_source(body)
		reparsed := ps_parse(emitted).body
		reemitted := code.program_node_to_source(reparsed)
		assert emitted == reemitted, 'canonical emit must be a fixpoint for `${src}`: `${emitted}` vs `${reemitted}`'
		assert emitted.contains(']/') || emitted.contains(']@') || emitted.contains('}.')
			|| emitted.contains(')/') || emitted.contains(')@'), 'the glued step run must survive emission of `${src}`: ${emitted}'
	}
}

// ── source: vcx/tests/typed_attr_test.v ──
// v08_typed_attr_test — D3 (conversions.md §2.1): typed scalar attributes
// `name::T=value` and their lossless CX⇄XML round-trip via the reserved
// `cx:attr-types` sidecar.
//
// Coverage:
//   • the glued `name::T=value` form PARSES (it previously fell through to
//     element body text) and coerces the value to T;
//   • attributes are scalar-only (D2) — an array type `::T[]` is an error;
//   • CX canonical emit: auto-recoverable types stay bare, atoms keep the
//     `:` sigil, sized/decimal/bigint/bytes carry the glued annotation;
//   • CX→XML emits a `cx:attr-types` sidecar listing exactly the types the
//     XML→CX auto-typer can't recover (and explicit-string-over-numeric);
//   • XML→CX import applies the sidecar (overriding) + auto-types the rest;
//   • the full CX→XML→CX round-trip is data-equivalent.

// canon renders via cx.emit_cx — the canonical-CX emitter behind
// `cx canonical` / `cx --to=cx`, i.e. the D3 round-trip path.
fn canon(src string) string {
	doc := cx.parse(src) or { return 'REJECT: ${err}' }
	return cx.emit_cx(doc).trim_space()
}

fn to_xml(src string) string {
	doc := cx.parse(src) or { return 'REJECT: ${err}' }
	return cx.emit_xml(doc).trim_space()
}

fn xml_to_cx(xml string) string {
	doc := cx.parse_xml(xml) or { return 'REJECT: ${err}' }
	return cx.emit_cx(doc).trim_space()
}

// ── parsing: the glued form is now a typed attribute, not body text ────────

fn test_typed_attr_parses() {
	doc := cx.parse('[event count::u16=5]') or {
		assert false, 'parse: ${err}'
		return
	}
	e := doc.elements[0] as cx.Element
	assert e.attrs.len == 1, 'expected 1 attr, got ${e.attrs.len} (items=${e.items.len})'
	a := e.attrs[0]
	assert a.name == 'count'
	dt := a.data_type() or {
		assert false, 'count has no data_type'
		return
	}
	assert dt == 'u16', 'expected u16, got ${dt}'
	assert a.value as i64 == 5
}

fn test_typed_attr_value_coercion() {
	// `::int`/`::u16` coerce to i64; `::decimal`/`::bigint`/`::atom` keep the
	// string payload; `::string` stays a raw string even over a numeric form.
	assert canon('[e n::i32=42]') == '[e n::i32=42]'
	assert canon('[e d::decimal=1.50]') == '[e d=1.50]' // I1 2b: fixed-point IS decimal — annotation redundant
	// I1 L45: over-i64 bigint drops the annotation (the bare image
	// auto-promotes to bigint, [L20]); a ≤ i64 bigint keeps it.
	assert canon('[e big::bigint=99999999999999999999]') == '[e big=99999999999999999999]'
	assert canon('[e small::bigint=42]') == '[e small::bigint=42]'
	assert canon('[e k::atom=urgent]') == '[e k=:urgent]' // atom canonicalises to the sigil
	assert canon("[e code::string=007]") == "[e code='007']"
}

// ── D2: attributes are scalar-only ─────────────────────────────────────────

fn test_array_type_attr_is_error() {
	r := canon('[e xs::int[]=5]')
	assert r.starts_with('REJECT'), r
	assert r.contains('CXER0100'), r
}

// ── canonical emit: auto-recoverable types stay bare (no annotation) ───────

fn test_auto_recoverable_stays_bare() {
	assert canon('[e count::int=5]') == '[e count=5]'
	assert canon('[e active::bool=true]') == '[e active=true]'
	assert canon('[e when::date=2024-01-15]') == '[e when=2024-01-15]'
}

// ── CX→XML: the cx:attr-types sidecar ──────────────────────────────────────

fn test_xml_sidecar_emit() {
	got := to_xml('[event count::u16=5 score::decimal=1.5 tag::atom=urgent host=db-1]')
	assert got == '<event count="5" score="1.5" tag="urgent" host="db-1" cx:attr-types="count=u16 score=decimal tag=atom"/>', got
}

fn test_xml_no_sidecar_when_all_auto() {
	// int/bool/date round-trip from the lexical form — no sidecar at all.
	got := to_xml('[event count=5 active=true when=2024-01-15 host=db-1]')
	assert got == '<event count="5" active="true" when="2024-01-15" host="db-1"/>', got
}

fn test_xml_sidecar_string_over_numeric() {
	// A quoted numeric-looking string would auto-type to int on import, so it
	// is pinned with a `=string` sidecar entry.
	got := to_xml("[event code='007']")
	assert got == '<event code="007" cx:attr-types="code=string"/>', got
}

// ── XML→CX: import auto-typing + sidecar application ────────────────────────

fn test_xml_import_autotypes() {
	got := xml_to_cx('<event count="5" active="true" when="2024-01-15" host="db-1"/>')
	assert got == '[event count=5 active=true when=2024-01-15 host=db-1]', got
}

fn test_xml_import_applies_sidecar() {
	got := xml_to_cx('<event count="5" score="1.5" tag="urgent" host="db-1" cx:attr-types="count=u16 score=decimal tag=atom"/>')
	assert got == '[event count::u16=5 score=1.5 tag=:urgent host=db-1]', got // I1 2b: bare 1.5 re-types decimal
}

fn test_xml_import_pins_string() {
	got := xml_to_cx('<event code="007" cx:attr-types="code=string"/>')
	assert got == "[event code='007']", got
}

// ── the round-trip is data-equivalent ──────────────────────────────────────

fn test_round_trip_equivalent() {
	src := '[event count::u16=5 score::decimal=1.5 tag::atom=urgent host=db-1]'
	round := xml_to_cx(to_xml(src))
	// canonicalise the source too — atoms normalise to the sigil form.
	assert round == canon(src), 'round=${round}\ncanon=${canon(src)}'
}

// ── source: vcx/tests/bare_url_attr_value_test.v ──
// bare_url_attr_value_test.v — a bare (unquoted) URL attribute value inside a
// PROGRAM (`[link href=https://x.com/a/b]`) is a parse error: the program
// attribute grammar reads the value as an expression (grammar [127c] — the
// same rule that admits `select=//a/b` as a CXPath PathExpr), so `://` after
// the scheme cannot be more string. DATA's BareValue ([L70]) admits URLs,
// which is exactly why users hit this — the diagnostic must say the fix
// (quote the value), not the pre-fix "expected identifier after ':' in atom
// literal, got '//'" left by the orphaned `: //` tokens.

fn cx_bin() string {
	return testenv.cx_bin()
}

fn tmp_doc(label string, content string) string {
	path := os.join_path(os.temp_dir(), 'cx_urlattr_${label}_${os.getpid()}.cx')
	os.write_file(path, content) or { panic(err) }
	return path
}

// ── 1. The reported repro: bare URL attr value fails with the quote hint ────

fn test_bare_url_attr_value_parse_error_carries_quote_hint() {
	src := '[?let [= \$x 1] [link href=https://x.com/a/b]]'
	cx.parse_program(src) or {
		msg := err.msg()
		assert msg.contains('CXER0100'), 'expected CXER0100, got: ${msg}'
		assert msg.contains("href='https://x.com/a/b'"),
			'expected the quote-the-value hint, got: ${msg}'
		assert !msg.contains('atom literal'),
			'the orphaned-colon atom-literal error must not surface: ${msg}'
		return
	}
	assert false, 'bare URL attr value must be a parse error'
}

// ── 2. Same shape through the computed-name [?element] body ─────────────────

fn test_bare_url_attr_value_in_computed_element_errors() {
	src := '[?element "link" href=https://x.com/a/b]'
	cx.parse_program(src) or {
		msg := err.msg()
		assert msg.contains("href='https://x.com/a/b'"),
			'expected the quote-the-value hint, got: ${msg}'
		return
	}
	assert false, 'bare URL attr value in [?element] must be a parse error'
}

// ── 3. The suggested fix works: the quoted value is a literal string ─────────

fn test_quoted_url_attr_value_parses_and_evaluates() {
	f := tmp_doc('quoted', "[?let [= \$x 1] [link href='https://x.com/a/b']]\n")
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code == 0, 'quoted URL attr value must evaluate, got: ${r.output}'
	assert r.output.contains('https://x.com/a/b'), 'URL lost: ${r.output}'
}

// ── 4. No regression: QName bare values still fold to one string ────────────

fn test_qname_bare_attr_values_still_fold() {
	f := tmp_doc('qname', '[?let [= \$x 1] [rect kind=svg:rect xmlns=urn:example]]\n')
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code == 0, 'QName bare attr value must still parse, got: ${r.output}'
	assert r.output.contains('svg:rect'), 'QName fold lost: ${r.output}'
	assert r.output.contains('urn:example'), 'QName fold lost: ${r.output}'
}

// ── 5. No regression: PathExpr-valued attrs stay expressions ([127c]) ────────

fn test_pathexpr_attr_value_still_parses_as_expression() {
	// `select=//a/b` is an intentional CXPath PathExpr attr value; the
	// bare-URL detection (ident ':' '//', byte-adjacent) must not touch it.
	cx.parse_program('[pick select=//a/b]') or {
		assert false, 'PathExpr attr value must still parse: ${err.msg()}'
		return
	}
}

// ── 6. The end-to-end CLI diagnostic (the reported UX) ───────────────────────

fn test_cli_diagnostic_hints_quoting() {
	f := tmp_doc('cli', '[?let [= \$x 1] [link href=https://x.com/a/b]]\n')
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
	assert r.exit_code != 0, 'bare URL attr value must fail loud, got: ${r.output}'
	assert r.output.contains('CXER0100'), 'expected CXER0100, got: ${r.output}'
	assert r.output.contains("href='https://x.com/a/b'"),
		'expected the quote-the-value hint, got: ${r.output}'
}

// ── source: vcx/tests/predicate_eval_test.v ──
// Tests for Phase 2.21-standalone — eval_predicate_filter, eager-iteration
// PredicateExpr evaluator.
//
// Coverage map (each §D3/§D4/§D5/§D7 contract gets at
// least one direct test):
//
//   - attr_test predicate filters candidates with the attr.
//   - attr_compare predicate (all 6 prefix ops `[OP $_@name V]`) filters
//     correctly; missing attribute → ABSENCE → comparison false (all ops,
//     including `!=`) — never an error.
//   - int_position predicate keeps only the Nth candidate.
//   - `$_position` reference inside predicate works.
//   - `$_last` reference works.
//   - bool_expr connectives `[and …]` / `[or …]` / `[not …]` evaluate
//     (EBV fold over children).
//   - `:bind NAME` from PredicateEvalContext is visible inside the predicate
//     (cross-step reference via reserved_binding-shaped AST).
//   - Empty candidate sequence → empty result, no error.
//   - Single-candidate sequence with passing predicate → [single].
//   - 3-candidate mixed pass/fail → expected filtered subset.
//   - EBV coercion: each table row gives the documented result.
//   - function_call count AST (hand-built — the paren-call SURFACE is
//     retired per #110) filters by children_count.
//   - Generic / unsupported predicate → MATCH_PREDICATE_EVAL_NOT_YET_IMPLEMENTED.
// ── helpers ─────────────────────────────────────────────────────────────────

fn elem(name string, attrs map[string]string) code.Item {
	return code.Item{
		kind:  'element'
		name:  name
		attrs: attrs.clone()
	}
}

fn elem_with_count(name string, attrs map[string]string, children int) code.Item {
	return code.Item{
		kind:           'element'
		name:           name
		attrs:          attrs.clone()
		children_count: children
	}
}

fn empty_ctx() code.PredicateEvalContext {
	return code.PredicateEvalContext{
		bindings: map[string]code.Value{}
	}
}

// ── attr_test ────────────────────────────────────────────────────────────────

fn test_attr_test_filters_present_attr() {
	candidates := [
		elem('user', {'active': 'true'}),
		elem('user', {}),
		elem('user', {'active': 'false'}),
	]
	pred := cx.predicate_expr_parse('@active') or {
		assert false, 'parse failed: ${err}'
		return
	}
	out := code.eval_predicate_filter(candidates, pred, empty_ctx()) or {
		assert false, 'filter failed: ${err}'
		return
	}
	assert out.len == 2
	// Attribute existence — value irrelevant.
	assert 'active' in out[0].attrs
	assert 'active' in out[1].attrs
}

fn test_attr_test_empty_input_empty_output() {
	candidates := []code.Item{}
	pred := cx.predicate_expr_parse('@x') or {
		assert false
		return
