	out := code.eval_predicate_filter(candidates, pred, empty_ctx()) or {
		assert false, '${err}'
		return
	}
	assert out.len == 0
}

fn test_attr_test_single_candidate_pass() {
	candidates := [elem('user', {'role': 'admin'})]
