		source: '\$t'
	}
	mut ctx := empty_ctx()
	ctx.bindings['t'] = code.value_bool(false)
	out := code.eval_predicate_filter(candidates, pred, ctx) or {
		assert false, '${err}'
		return
	}
	assert out.len == 0
}

